<template><ion-page><ion-header><ion-toolbar><ion-buttons slot="start"><ion-back-button default-href="/professor/home"/></ion-buttons><ion-title><span class="toolbar-page-title">Editar atividade</span><span class="toolbar-brand-right">Task<span>Edu</span></span></ion-title></ion-toolbar></ion-header><ion-content><main class="form-page wide-form"><header class="form-hero"><span>EDIÇÃO</span><h1>Atualize o compromisso</h1><p>As alterações serão exibidas imediatamente para a turma.</p></header><section class="form-card"><LoadingGrid v-if="carregando"/><AtividadeForm v-else :inicial="inicial" :salvando="salvando" :erro="erro" rotulo="Salvar alterações" @salvar="salvar"/></section></main></ion-content></ion-page></template>
<script setup lang="ts">import { onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { IonBackButton,IonButtons,IonContent,IonHeader,IonPage,IonTitle,IonToolbar,toastController } from '@ionic/vue';import AtividadeForm,{type FormAtividade} from '../components/AtividadeForm.vue';import LoadingGrid from '../components/LoadingGrid.vue';import { atualizarAtividade,buscarAtividade } from '../services/atividades.service';import { getUsuarioAtual } from '../services/auth.service';import { formatarISO } from '../utils/datas';const route=useRoute(),router=useRouter(),usuario=getUsuarioAtual(),carregando=ref(true),salvando=ref(false),erro=ref(''),inicial=ref<Partial<FormAtividade>>({});onMounted(async()=>{const atividade=await buscarAtividade(String(route.params.id));if(!atividade||atividade.professorId!==usuario.value?.uid){await router.replace('/professor/home');return}const data=atividade.dataEntrega.toDate();inicial.value={titulo:atividade.titulo||atividade.descricao,descricao:atividade.descricao,materia:atividade.materia,turma:atividade.turma,tipo:atividade.tipo,prioridade:atividade.prioridade||'Média',data:formatarISO(data),horario:`${String(data.getHours()).padStart(2,'0')}:${String(data.getMinutes()).padStart(2,'0')}`};carregando.value=false});async function salvar(dados:FormAtividade){salvando.value=true;erro.value='';try{await atualizarAtividade(String(route.params.id),{...dados,dataEntrega:new Date(`${dados.data}T${dados.horario||'23:59'}:00`)});const toast=await toastController.create({message:'Atividade atualizada!',duration:1600,color:'success',position:'top'});await toast.present();await router.replace('/professor/home')}catch(e){erro.value=e instanceof Error?e.message:'Não foi possível atualizar.'}finally{salvando.value=false}}</script>
